/* ===== core/40-make-shareable.js ===== */
/* core/40-make-shareable.js  |  PF v1.4.3 | MAKE SHAREABLE — inline Studio creation panel.
   CEO directive 2026-10-07 ~01:38 CDT ("further integration via EMBEDDING"):
   Studio creation tools on every data page. One-click "make shareable" from
   any data view — no separate trip to /studio or /create required.

   ONE module, five data products (/receipt, /town, /extraction, /index, /karl):
   - Pages register shareable units — one per dossier / town report / story /
     score / answer — via PFMakeShareable.units([...]). Units may also be
     declared in markup: any element with [data-mss] is picked up by the
     scanner (data-mss-kind, data-mss-ref, data-mss-painter, data-mss-title,
     data-mss-deep, data-mss-game).
   - The module injects a MAKE SHAREABLE button into each unit (once;
     a MutationObserver re-scans for async-rendered cards, so late mounts
     and feed pages are covered).
   - One tap opens an INLINE bottom-sheet panel (never a page navigation):
     the product's OWN 1080x1350 painter renders the preview (no duplicate
     image code — resolution via PFShare.paintAsync or a page-registered
     resolver), the user can add a caption/context line, and one PUBLISH
     tap sends the piece to the UGC feed (the builders' PFUgcCreate contract)
     AND opens the native share sheet.

   RULES (standing):
   - Inline panel, never a page. The user never leaves the data view.
   - Zero XP for viewing — this module never touches the XP ledger.
     Publishing routes through PFShare.shareImage (claimGate + creditShare),
     i.e. the existing share mechanics — nothing new invented.
   - Mobile-first: the sheet is thumb-reachable, PUBLISH is a 52px target
     pinned at the bottom of the sheet.
   - Clean, light (CEO design direction): white sheet, ink text, red CTA.

   Painter resolution per unit (first hit wins):
     1. resolvers[kind](unit, done) — registered by the page when its painter
        needs live JSON held in a module closure (receipt dossier, town
        report, extraction profile, karl answer).
     2. PFShare.paintAsync(unit.painter, done) — custom painters registered
        via PFShare.setPoster, or REG ids via the generic renderer.

   UGC publish contract (specs/mss-ugc-publish-contract-20261007.md):
     window.PFUgcCreate.publish({kind, ref, title, caption, deepLink,
       imageBlob, gameId}) -> Promise<{ok, slug?, url?}>.
   Fail-soft: a builder that hasn't landed yet is NOT a wedge — the piece is
   queued device-local (pf_mss_queue_v1, cap 25, metadata only — the image
   re-paints from the unit's painter when the builder consumes the queue)
   and the native share sheet still opens. Events 'pf-mss-published' and
   'pf-mss-queued' fire on document for builders/observers.

   KILL: ?pf_off=make-shareable  or  localStorage pf_disabled_v1='["make-shareable"]' */
(function () {
  'use strict';
  var PF = window.PF;
  if (!PF || PF.skip('make-shareable')) { return; }
  if (window.pfMakeShareableDone) return;
  window.pfMakeShareableDone = true;

  var QUEUE_KEY = 'pf_mss_queue_v1';
  var QUEUE_CAP = 25;
  var CAPTION_MAX = 140;

  function esc(s) {
    return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;')
      .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }
  function toast(m) { try { if (PF && PF.toast) PF.toast(m); } catch (e) {} }
  function err(m) { try { if (PF && PF.error) PF.error('make-shareable', m); } catch (e) {} }
  function isEditor() {
    try {
      var h = window.location.href || '';
      if (h.indexOf('/config/') !== -1) return true;
      var b = document.body;
      if (b && (b.classList.contains('sqs-edit-mode') || b.classList.contains('sqs-editing'))) return true;
    } catch (e) {}
    return false;
  }
  if (isEditor()) return;

  function safeRef(r) {
    return String(r == null ? 'item' : r).toLowerCase().replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '').slice(0, 60) || 'item';
  }
  function absUrl(deep) {
    var d = String(deep || '/');
    if (/^https?:\/\//i.test(d)) return d;
    if (d.charAt(0) !== '/') d = '/' + d;
    return 'https://www.mtcstw.com' + d;
  }
  function callsign() {
    try { return window.PFCallsign ? String(window.PFCallsign() || '') : ''; } catch (e) { return ''; }
  }

  /* ---------------------------------------------------------------- */
  /* CSS — clean, light sheet. Mobile-first, thumb-reachable.           */
  /* ---------------------------------------------------------------- */
  function cssOnce() {
    if (document.getElementById('pf-mss-css')) return;
    var css = [
      '.pf-mss-btn{display:inline-block;background:#fff;border:2px solid #c1121f;color:#c1121f;',
      'font-weight:900;letter-spacing:2px;font-size:13px;padding:12px 22px;border-radius:8px;',
      'cursor:pointer;min-height:44px;font-family:Arial,sans-serif;margin:10px 0 2px}',
      '.pf-mss-btn:hover{background:#c1121f;color:#fff}',
      '.pf-mss-btn:active{transform:scale(.98)}',
      '.pf-mss-btn:focus-visible{outline:3px solid #c1121f;outline-offset:2px}',
      /* Butter pass (workstream 5): premium bottom-sheet chrome — drag
         grip, PFN-red top accent, lifted PUBLISH with hover states. */
      '.pf-mss-grip{width:44px;height:5px;border-radius:3px;background:#d8d2bd;margin:10px auto 2px}',
      '.pf-mss-x:hover{color:#c1121f}',
      '.pf-mss-pub{box-shadow:0 3px 14px rgba(193,18,31,.4);',
      'transition:background .15s ease,transform .12s ease,box-shadow .15s ease}',
      '.pf-mss-pub:hover:not(:disabled){background:#e01424;transform:translateY(-1px);',
      'box-shadow:0 8px 22px rgba(193,18,31,.5)}',
      '.pf-mss-pub:active:not(:disabled){transform:scale(.98)}',
      '.pf-mss-pub:focus-visible{outline:3px solid #1a1814;outline-offset:2px}',
      '@media(prefers-reduced-motion:reduce){.pf-mss-sheet{animation:none}.pf-mss-pub:hover{transform:none}}',
      '.pf-mss-scrim{position:fixed;inset:0;background:rgba(10,8,6,.55);z-index:2147483000;}',
      '.pf-mss-sheet{position:fixed;left:0;right:0;bottom:0;z-index:2147483001;background:#fdfdfa;',
      'border-top:4px solid #c1121f;',
      'border-radius:16px 16px 0 0;box-shadow:0 -8px 40px rgba(0,0,0,.35);max-width:560px;margin:0 auto;',
      'max-height:92vh;display:flex;flex-direction:column;font-family:Arial,sans-serif;color:#1a1814;',
      'animation:pfMssUp .22s ease-out}',
      '@keyframes pfMssUp{from{transform:translateY(40px);opacity:.4}to{transform:none;opacity:1}}',
      '.pf-mss-head{display:flex;align-items:center;justify-content:space-between;padding:14px 18px 10px;',
      'border-bottom:2px dashed #e7e1d0}',
      '.pf-mss-title{font-weight:900;letter-spacing:3px;font-size:14px;color:#c1121f}',
      '.pf-mss-x{background:none;border:0;font-size:22px;line-height:1;color:#8a8474;cursor:pointer;',
      'min-width:44px;min-height:44px;padding:8px}',
      '.pf-mss-body{padding:14px 18px;overflow-y:auto;-webkit-overflow-scrolling:touch}',
      '.pf-mss-prevwrap{text-align:center;margin-bottom:12px}',
      '.pf-mss-prev{max-width:100%;max-height:38vh;border:1px solid #e7e1d0;border-radius:8px;background:#fff}',
      '.pf-mss-loading{padding:34px 0;color:#8a8474;font-size:14px;text-align:center}',
      '.pf-mss-err{padding:20px 0;color:#c1121f;font-size:14px;text-align:center}',
      '.pf-mss-caplabel{font-size:11px;letter-spacing:3px;font-weight:900;color:#c1121f;margin:4px 0 6px}',
      '.pf-mss-cap{width:100%;box-sizing:border-box;background:#fff;border:2px solid #1a1814;color:#1a1814;',
      'padding:12px 14px;font-size:16px;border-radius:8px;outline:none;font-family:Arial,sans-serif}',
      '.pf-mss-cap:focus{border-color:#c1121f}',
      '.pf-mss-note{font-size:12px;color:#8a8474;margin:10px 0 0;line-height:1.5;text-align:center}',
      '.pf-mss-foot{padding:12px 18px 18px;border-top:1px solid #e7e1d0;background:#fdfdfa}',
      '.pf-mss-pub{display:block;width:100%;background:#c1121f;border:0;color:#fff;font-weight:900;',
      'letter-spacing:2px;font-size:16px;padding:16px;border-radius:10px;cursor:pointer;min-height:52px}',
      '.pf-mss-pub:disabled{opacity:.55;cursor:wait}',
      '@media(prefers-reduced-motion:reduce){.pf-mss-pub{transition:none}}'
    ];
    var st = document.createElement('style');
    st.id = 'pf-mss-css';
    st.textContent = css.join('\n');
    document.head.appendChild(st);
  }

  /* ---------------------------------------------------------------- */
  /* Unit registry                                                     */
  /* ---------------------------------------------------------------- */
  /* unit: {el, kind, ref, title, deep, game, painter} */
  var unitList = [];
  var resolvers = {};

  function unitKey(u) {
    return String(u.kind || '') + '|' + String(u.ref || '');
  }
  var seenKeys = {};

  function addUnits(units) {
    if (!units || !units.length) return;
    for (var i = 0; i < units.length; i++) {
      var u = units[i];
      if (!u || !u.el || !u.kind) continue;
      var k = unitKey(u);
      if (seenKeys[k]) continue;
      seenKeys[k] = 1;
      unitList.push(u);
      injectButton(u);
    }
  }

  function scanDeclarative(root) {
    var els = null;
    try { els = (root || document).querySelectorAll('[data-mss]:not([data-mss-wired])'); }
    catch (e) { return; }
    var found = [];
    for (var i = 0; i < els.length; i++) {
      (function (el) {
        el.setAttribute('data-mss-wired', '1');
        var kind = el.getAttribute('data-mss-kind') || 'ugc';
        found.push({
          el: el,
          kind: kind,
          ref: el.getAttribute('data-mss-ref') || '',
          title: el.getAttribute('data-mss-title') || 'The Propaganda Factory',
          deep: el.getAttribute('data-mss-deep') || '/',
          game: el.getAttribute('data-mss-game') || kind,
          painter: el.getAttribute('data-mss') || null
        });
      })(els[i]);
    }
    addUnits(found);
  }

  /* ---------------------------------------------------------------- */
  /* MAKE SHAREABLE button injection                                   */
  /* ---------------------------------------------------------------- */
  function injectButton(u) {
    try {
      var el = u.el;
      if (!el || el.querySelector(':scope > .pf-mss-btn')) return;
      var slot = null;
      try { slot = el.querySelector('[data-mss-slot]'); } catch (e) {}
      var b = document.createElement('button');
      b.type = 'button';
      b.className = 'pf-mss-btn';
      b.textContent = 'MAKE SHAREABLE';
      b.setAttribute('aria-label', 'Make this shareable — open the creation panel');
      b.addEventListener('click', function (ev) {
        try { ev.preventDefault(); ev.stopPropagation(); } catch (e) {}
        openPanel(u);
      });
      if (slot) slot.appendChild(b);
      else el.appendChild(b);
      u.btn = b;
    } catch (e) { err('inject failed'); }
  }

  /* ---------------------------------------------------------------- */
  /* Painting — the product's own painter, never duplicated.           */
  /* ---------------------------------------------------------------- */
  function paintUnit(u, done) {
    done = (typeof done === 'function') ? done : function () {};
    var r = null;
    try { r = resolvers[u.kind]; } catch (e) {}
    if (typeof r === 'function') {
      try { r(u, done); } catch (e) { try { done(null); } catch (e2) {} }
      return;
    }
    var P = null;
    try { P = window.PFShare; } catch (e) {}
    if (P && typeof P.paintAsync === 'function' && u.painter) {
      try { P.paintAsync(u.painter, done); } catch (e) { try { done(null); } catch (e2) {} }
      return;
    }
    if (P && typeof P.poster === 'function' && u.painter) {
      var cv = null;
      try { cv = P.poster(u.painter); } catch (e) {}
      try { done(cv); } catch (e2) {}
      return;
    }
    try { done(null); } catch (e) {}
  }

  function canvasToBlob(cv, cb) {
    try {
      if (cv.toBlob) { cv.toBlob(function (b) { cb(b); }, 'image/png'); return; }
      var u = cv.toDataURL('image/png');
      fetch(u).then(function (r) { return r.blob(); }).then(cb).catch(function () { cb(null); });
    } catch (e) { cb(null); }
  }

  /* ---------------------------------------------------------------- */
  /* UGC publish — the builders' contract, fail-soft.                  */
  /* ---------------------------------------------------------------- */
  function queueDraft(p) {
    var q = [];
    try { q = JSON.parse(localStorage.getItem(QUEUE_KEY) || '[]'); } catch (e) { q = []; }
    if (!Array.isArray(q)) q = [];
    q.push({
      kind: p.kind, ref: p.ref, title: p.title, caption: p.caption,
      deepLink: p.deepLink, gameId: p.gameId, ts: Date.now()
    });
    while (q.length > QUEUE_CAP) q.shift();
    try { localStorage.setItem(QUEUE_KEY, JSON.stringify(q)); } catch (e) {}
    try {
      document.dispatchEvent(new CustomEvent('pf-mss-queued', {
        detail: { kind: p.kind, ref: p.ref, queued: q.length }
      }));
    } catch (e) {}
  }

  /* One PUBLISH tap: UGC feed first, then the native share sheet.
     The sheet is never held hostage by the feed — a feed failure still
     shares the image. */
  function publish(unit, caption, cv, ui) {
    var filename = 'pfn-' + safeRef(unit.kind) + '-' + safeRef(unit.ref) + '.png';
    var shareTxt = caption ? (caption + '\n' + absUrl(unit.deep)) : null;

    function openSheet() {
      var P = null;
      try { P = window.PFShare; } catch (e) {}
      try {
        if (ui && ui.done) ui.done();
      } catch (e) {}
      if (P && typeof P.shareImage === 'function') {
        /* claimGate + creditShare ride inside shareImage — the existing
           share mechanics, zero new XP plumbing. */
        try { P.shareImage(cv, filename, unit.title, unit.game, shareTxt ? { text: shareTxt } : null); }
        catch (e) {
          try { P.saveImage(cv, filename, unit.game); } catch (e2) {}
          toast('Image saved — share it from your photos.');
        }
      } else {
        toast('Share unavailable — try again.');
      }
    }

    function feedThenSheet() {
      var payload = {
        kind: unit.kind, ref: unit.ref, title: unit.title,
        caption: caption, deepLink: unit.deep, imageBlob: null, gameId: unit.game
      };
      canvasToBlob(cv, function (blob) {
        payload.imageBlob = blob;
        var P = null;
        try { P = window.PFUgcCreate; } catch (e) {}
        var publishFn = (P && typeof P.publish === 'function') ? P.publish : null;
        if (!publishFn) {
          /* Builder not landed yet: queue device-local, never wedge. */
          payload.imageBlob = null; /* blobs don't serialize — repaints on consume */
          queueDraft(payload);
          toast('Saved to your share queue — feed publish lands with the builder.');
          openSheet();
          return;
        }
        var settled = false;
        function finish(ok) {
          if (settled) return; settled = true;
          try {
            document.dispatchEvent(new CustomEvent('pf-mss-published', {
              detail: { kind: unit.kind, ref: unit.ref, ok: !!ok }
            }));
          } catch (e) {}
          if (ok) toast('Published to the feed. Now spread it.');
          else toast('Feed hiccuped — sharing the image anyway.');
          openSheet();
        }
        try {
          var r = publishFn(payload);
          if (r && typeof r.then === 'function') {
            r.then(function (res) { finish(res && res.ok); }, function () { finish(false); });
            setTimeout(function () { finish(false); }, 20000); /* never wedge */
          } else { finish(!!r); }
        } catch (e) { finish(false); }
      });
    }

    /* UGC publish routes through the callsign — the builders require one.
       Dismissed claim: skip the feed silently, still open the sheet —
       never trap the user, never a misleading "hiccup" toast. */
    if (!callsign() && PF && typeof PF.requireCallsign === 'function') {
      try {
        PF.requireCallsign(function () {
          if (callsign()) feedThenSheet();
          else openSheet();
        }, {
          context: 'to publish your shareable to the feed'
        });
        return;
      } catch (e) { /* fall through to feed-then-sheet */ }
    }
    feedThenSheet();
  }

  /* ---------------------------------------------------------------- */
  /* Inline panel — bottom sheet, never a page navigation.              */
  /* ---------------------------------------------------------------- */
  var openState = null;

  function closePanel() {
    try {
      if (openState && openState.root && openState.root.parentNode) {
        openState.root.parentNode.removeChild(openState.root);
      }
    } catch (e) {}
    openState = null;
  }

  function openPanel(unit) {
    if (!unit) return;
    closePanel();
    cssOnce();
    var root = document.createElement('div');
    root.innerHTML =
      '<div class="pf-mss-scrim" data-mss-close></div>' +
      '<div class="pf-mss-sheet" role="dialog" aria-modal="true" aria-label="Make shareable">' +
      '<div class="pf-mss-grip" aria-hidden="true"></div>' +
      '<div class="pf-mss-head"><div class="pf-mss-title">MAKE SHAREABLE</div>' +
      '<button class="pf-mss-x" type="button" data-mss-close aria-label="Close">&times;</button></div>' +
      '<div class="pf-mss-body">' +
      '<div class="pf-mss-prevwrap" data-mss-prev><div class="pf-mss-loading">Painting your image&hellip;</div></div>' +
      '<div class="pf-mss-caplabel">YOUR CONTEXT LINE (OPTIONAL)</div>' +
      '<input class="pf-mss-cap" type="text" maxlength="' + CAPTION_MAX + '" data-mss-cap ' +
      'placeholder="Add your take — one line, your words&hellip;" aria-label="Caption or context line">' +
      '<div class="pf-mss-note">Publishes to the UGC feed, then opens your share sheet.<br>' +
      'Zero XP for viewing — sharing counts through the usual share mechanics.</div>' +
      '</div>' +
      '<div class="pf-mss-foot"><button class="pf-mss-pub" type="button" data-mss-pub disabled>PUBLISH</button></div>' +
      '</div>';
    document.body.appendChild(root);
    openState = { root: root, unit: unit, canvas: null };

    function wireClose() {
      var closers = root.querySelectorAll('[data-mss-close]');
      for (var i = 0; i < closers.length; i++) {
        closers[i].addEventListener('click', closePanel);
      }
    }
    wireClose();
    try {
      document.addEventListener('keydown', function esc2(e) {
        if (e && e.key === 'Escape' && openState && openState.root === root) {
          closePanel();
          document.removeEventListener('keydown', esc2);
        }
      });
    } catch (e) {}

    var prevWrap = root.querySelector('[data-mss-prev]');
    var pubBtn = root.querySelector('[data-mss-pub]');
    var capInput = root.querySelector('[data-mss-cap]');

    paintUnit(unit, function (cv) {
      if (!openState || openState.root !== root) return; /* panel closed meanwhile */
      if (!cv) {
        prevWrap.innerHTML = '<div class="pf-mss-err">Couldn\u2019t paint the preview.' +
          ' <button type="button" class="pf-mss-btn" data-mss-retry>RETRY</button></div>';
        var rb = prevWrap.querySelector('[data-mss-retry]');
        if (rb) rb.addEventListener('click', function () {
          prevWrap.innerHTML = '<div class="pf-mss-loading">Painting your image&hellip;</div>';
          openPanel(unit);
        });
        return;
      }
      openState.canvas = cv;
      var img = document.createElement('img');
      img.className = 'pf-mss-prev';
      img.alt = 'Share image preview';
      try { img.src = cv.toDataURL('image/png'); } catch (e) { img.src = ''; }
      prevWrap.innerHTML = '';
      prevWrap.appendChild(img);
      pubBtn.disabled = false;
      try { capInput.focus({ preventScroll: true }); } catch (e) {}
    });

    pubBtn.addEventListener('click', function () {
      if (!openState || !openState.canvas || pubBtn.disabled) return;
      pubBtn.disabled = true;
      pubBtn.textContent = 'PUBLISHING\u2026';
      var caption = '';
      try { caption = String(capInput.value || '').trim().slice(0, CAPTION_MAX); } catch (e) {}
      publish(unit, caption, openState.canvas, { done: closePanel });
    });
  }

  /* ---------------------------------------------------------------- */
  /* Scan — initial + MutationObserver for async renders.              */
  /* ---------------------------------------------------------------- */
  var scanTimer = null;
  function scheduleScan() {
    if (scanTimer) return;
    scanTimer = setTimeout(function () {
      scanTimer = null;
      try { scanDeclarative(document); } catch (e) {}
    }, 350);
  }
  function observe() {
    try {
      var mo = new MutationObserver(function () { scheduleScan(); });
      mo.observe(document.body || document.documentElement, { childList: true, subtree: true });
    } catch (e) {}
  }

  /* ---------------------------------------------------------------- */
  /* Public API                                                        */
  /* ---------------------------------------------------------------- */
  window.PFMakeShareable = {
    units: addUnits,
    registerResolver: function (kind, fn) {
      try { if (kind && typeof fn === 'function') resolvers[String(kind)] = fn; } catch (e) {}
    },
    openPanel: openPanel,
    closePanel: closePanel,
    scan: function () { try { scanDeclarative(document); } catch (e) {} },
    version: '1.4.3-mss1'
  };

  /* Boot: scan now (some units render before us) and watch for the rest. */
  try { scanDeclarative(document); } catch (e) {}
  observe();
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () {
      try { scanDeclarative(document); } catch (e) {}
    });
  }
  setTimeout(function () { try { scanDeclarative(document); } catch (e) {} }, 2500);
})();

;

/* ===== pages/index-page.js ===== */
/* pages/index-page.js | PF v1.4.3 | THE CORRUPTION INDEX (/index).
   CEO directive 2026-10-07 "Let it blossom" — Product 4 of 5.
   Design direction: clean leaderboard, light. Scores and methodology
   immediately clear; input breakdowns expand on tap. No bloated pages.

   STICKY WEB (not a maze): every score links to its natural neighbors —
   the full Receipt dossier is ONE prominent tap away (primary neighbor),
   plus the entity's town (/town) and related extraction story
   (/extraction/<slug> for companies).

   Mounts into <div id="pf-index"></div> on the Squarespace /index page.
   JSONP reads of index_scores / index_entity / index_methodology
   (be/data-corruption-index, v172) — public, read-only, ZERO XP.
   Copy rules: scores describe capture ("highly captured"), never accuse;
   vote-money is "alignment" only. No entity scores below the data
   threshold — otherwise the honest "insufficient data" state.

   KILL: ?pf_off=corruption-index or localStorage pf_disabled_v1.
   Deep link: /index#<slug> expands that entity. */
(function () {
  'use strict';
  var PF = window.PF;
  if (window.pfCorruptionIndexDone) return;
  if (PF && PF.skip('corruption-index')) return;
  var host = document.getElementById('pf-index');
  if (!host) { if (PF) PF.error('corruption-index', 'mount div #pf-index missing — skipping'); return; }
  if (isEditor()) return;
  window.pfCorruptionIndexDone = true;

  function isEditor() {
    try {
      var h = window.location.href || '';
      if (h.indexOf('/config/') !== -1) return true;
      var b = document.body;
      if (b && (b.classList.contains('sqs-edit-mode') || b.classList.contains('sqs-editing'))) return true;
      return false;
    } catch (e) { return false; }
  }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function apiBase() {
    try { return window.PF_BACKEND_URL || 'https://pf-api.mtcstw.workers.dev'; }
    catch (e) { return 'https://pf-api.mtcstw.workers.dev'; }
  }
  var cbN = 0;
  function jsonp(action, params, done) {
    var fn = 'pfIdxCb' + (++cbN) + '_' + Date.now();
    var q = '?action=' + encodeURIComponent(action) + '&callback=' + fn;
    for (var k in params) {
      if (params[k] != null) q += '&' + encodeURIComponent(k) + '=' + encodeURIComponent(params[k]);
    }
    var timer = null, finished = false;
    window[fn] = function (data) {
      if (finished) return; finished = true;
      clearTimeout(timer);
      try { delete window[fn]; } catch (e) { window[fn] = null; }
      done(data);
    };
    timer = setTimeout(function () {
      if (finished) return; finished = true;
      try { delete window[fn]; } catch (e) { window[fn] = null; }
      done(null);
    }, 12000);
    var s = document.createElement('script');
    s.async = true;
    s.onerror = function () { if (!finished) { finished = true; clearTimeout(timer); done(null); } };
    s.src = apiBase() + q;
    try { document.head.appendChild(s); } catch (e) { done(null); }
  }

  /* ---------- styles: light, airy, mobile-first ---------- */
  function injectCSS() {
    if (document.getElementById('pf-idx-css')) return;
    var st = document.createElement('style');
    st.id = 'pf-idx-css';
    st.textContent =
      '#pf-index{font-family:Arial,Helvetica,sans-serif;color:#f5ead6;max-width:720px;margin:0 auto;padding:0 12px 40px;box-sizing:border-box}' +
      '.pf-idx-head{text-align:center;padding:26px 8px 6px}' +
      '.pf-idx-kicker{font-size:11px;letter-spacing:.32em;color:#e5383b;font-weight:800}' +
      '.pf-idx-head h1{font-family:"Arial Black",Arial,sans-serif;font-size:30px;margin:8px 0 6px;letter-spacing:.02em}' +
      '.pf-idx-sub{color:#a89e88;font-size:14px;line-height:1.5;max-width:520px;margin:0 auto}' +
      '.pf-idx-chips{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin:16px 0 4px}' +
      '.pf-idx-chip{font-size:11px;font-weight:700;letter-spacing:.06em;background:#161616;border:1px solid #333;border-radius:20px;padding:7px 13px;color:#c9bfa8}' +
      '.pf-idx-meth{margin:12px auto 0;max-width:640px;background:#111;border:1px solid #2a2a2a;border-radius:10px}' +
      '.pf-idx-meth>summary{cursor:pointer;padding:13px 16px;font-size:13px;font-weight:800;letter-spacing:.08em;color:#e8b923;list-style:none}' +
      '.pf-idx-meth>summary::-webkit-details-marker{display:none}' +
      '.pf-idx-meth .pf-idx-methbody{padding:0 16px 16px;font-size:13px;line-height:1.65;color:#c9bfa8}' +
      '.pf-idx-meth table{width:100%;border-collapse:collapse;margin:8px 0;font-size:12px}' +
      '.pf-idx-meth td,.pf-idx-meth th{border-bottom:1px solid #2a2a2a;padding:7px 6px;text-align:left;vertical-align:top}' +
      '.pf-idx-meth th{color:#e8b923;font-size:11px;letter-spacing:.08em}' +
      '.pf-idx-tabs{display:flex;gap:8px;justify-content:center;margin:20px 0 6px}' +
      '.pf-idx-tab{flex:1;max-width:220px;text-align:center;padding:11px 0;font-size:13px;font-weight:900;letter-spacing:.12em;background:#161616;border:1px solid #333;border-radius:8px;color:#a89e88;cursor:pointer}' +
      '.pf-idx-tab.on{background:#c1121f;border-color:#c1121f;color:#fff}' +
      '.pf-idx-vint{text-align:center;font-size:11px;color:#a89e88;letter-spacing:.1em;margin:8px 0 4px}' +
      '.pf-idx-list{margin:0;padding:0;list-style:none}' +
      '.pf-idx-row{border-bottom:1px solid #222;padding:14px 6px;cursor:pointer}' +
      '.pf-idx-row:active{background:#141414}' +
      '.pf-idx-top{display:flex;align-items:center;gap:12px}' +
      '.pf-idx-rank{font-family:"Arial Black",Arial,sans-serif;font-size:15px;color:#a89e88;min-width:30px;text-align:center}' +
      '.pf-idx-who{flex:1;min-width:0}' +
      '.pf-idx-name{font-size:16px;font-weight:800;color:#f5ead6;line-height:1.25}' +
      '.pf-idx-meta{font-size:11px;color:#a89e88;letter-spacing:.06em;margin-top:3px}' +
      '.pf-idx-score{text-align:right}' +
      '.pf-idx-num{font-family:"Arial Black",Arial,sans-serif;font-size:30px;color:#e8b923;line-height:1}' +
      '.pf-idx-label{font-size:10px;font-weight:800;letter-spacing:.14em;color:#e5383b;margin-top:4px}' +
      '.pf-idx-bars{display:flex;gap:4px;margin-top:10px}' +
      '.pf-idx-bar{flex:1;height:5px;border-radius:3px;background:#2a2a2a;overflow:hidden}' +
      '.pf-idx-bar i{display:block;height:100%;background:#c1121f}' +
      '.pf-idx-bar.off i{background:transparent}' +
      '.pf-idx-detail{display:none;padding:14px 2px 6px}' +
      '.pf-idx-row.open .pf-idx-detail{display:block}' +
      '.pf-idx-in{border-top:1px dashed #333;padding:10px 0}' +
      '.pf-idx-in-t{display:flex;justify-content:space-between;gap:10px;font-size:13px;font-weight:800}' +
      '.pf-idx-in-t .w{color:#e8b923;font-weight:700;font-size:11px}' +
      '.pf-idx-in-v{font-size:13px;color:#f5ead6;margin-top:4px}' +
      '.pf-idx-in-e{font-size:12px;color:#a89e88;margin-top:4px;font-style:italic}' +
      '.pf-idx-in-s{font-size:10px;color:#8f887a;letter-spacing:.06em;margin-top:5px}' +
      '.pf-idx-in-s a{color:#8f887a}' +
      '.pf-idx-receipt{display:block;text-align:center;background:#c1121f;color:#fff;font-weight:900;letter-spacing:.1em;font-size:14px;padding:14px;border-radius:8px;margin:14px 0 8px;text-decoration:none}' +
      '.pf-idx-receipt:active{transform:scale(.98)}' +
      '.pf-idx-web{display:flex;gap:8px;margin:0 0 6px}' +
      '.pf-idx-web a{flex:1;text-align:center;font-size:12px;font-weight:700;letter-spacing:.06em;color:#c9bfa8;border:1px solid #333;border-radius:8px;padding:10px 4px;text-decoration:none;background:#141414}' +
      '.pf-idx-share{display:block;width:100%;background:none;border:1px solid #444;color:#e8b923;font-weight:800;letter-spacing:.1em;font-size:12px;padding:10px;border-radius:8px;margin:8px 0 2px;cursor:pointer}' +
      '.pf-idx-empty{text-align:center;padding:30px 16px;color:#a89e88}' +
      '.pf-idx-empty h3{color:#f5ead6;font-family:"Arial Black",Arial,sans-serif;font-size:18px;margin:0 0 10px}' +
      '.pf-idx-empty p{font-size:13px;line-height:1.6;max-width:480px;margin:0 auto 14px}' +
      '.pf-idx-rails{display:inline-block;text-align:left;font-size:12px;line-height:2;background:#111;border:1px solid #2a2a2a;border-radius:10px;padding:12px 18px;margin:0 auto}' +
      '.pf-idx-load{text-align:center;color:#a89e88;padding:40px 0;font-size:14px}' +
      '.pf-idx-err{text-align:center;color:#f5ead6;background:#1a0505;border:2px solid #c1121f;border-radius:10px;padding:18px;margin:20px 0;font-size:14px}';
    try { document.head.appendChild(st); } catch (e) {}
  }
  injectCSS();

  var state = { tab: 'politicians', scores: null, meth: null, detailCache: {} };

  function vintageLine(w) {
    if (!w) return '';
    var m = String(w).match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (!m) return esc(w);
    var MON = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
    return 'WEEK OF ' + MON[parseInt(m[2], 10) - 1] + ' ' + parseInt(m[3], 10) + ', ' + m[1];
  }

  function methodologyHTML() {
    var m = state.meth;
    if (!m) return '<div class="pf-idx-methbody">Methodology loading…</div>';
    function wrows(list) {
      return list.map(function (r) {
        return '<tr><td><b>' + esc(r.title) + '</b><br><span style="color:#8f887a">' + esc(r.desc || '') + '</span></td>' +
          '<td>' + Math.round(r.weight * 100) + '%</td><td>' + esc(r.source || '') + '</td></tr>';
      }).join('');
    }
    return '<div class="pf-idx-methbody">' +
      '<p>' + esc(m.subtitle || '') + ' ' + esc(m.what || '') + '</p>' +
      '<table><tr><th>Politician input</th><th>Weight</th><th>Source</th></tr>' + wrows(m.weights.politician) + '</table>' +
      '<table><tr><th>Company input</th><th>Weight</th><th>Source</th></tr>' + wrows(m.weights.company) + '</table>' +
      '<p><b>Data threshold:</b> politicians — ' + esc(m.threshold.politicians) + '; companies — ' + esc(m.threshold.companies) +
      '. Below the threshold: <i>insufficient data</i>, never a score.</p>' +
      '<p><b>Display band:</b> ' + esc(m.band) + '</p>' +
      '<p><b>Vintage:</b> ' + esc(m.vintage_policy) + '</p>' +
      '<p><b>Copy rules:</b> ' + m.copy_rules.map(esc).join(' ') + '</p></div>';
  }

  function metaLine(r) {
    if (state.tab === 'companies') return esc(r.industry || 'COMPANY');
    var bits = [];
    if (r.office) bits.push(r.office.toUpperCase());
    if (r.state) bits.push(r.state);
    if (r.party) bits.push(r.party);
    return esc(bits.join(' · '));
  }

  function rowHTML(r) {
    var bars = '';
    /* input mini-bars: live count filled; exact norms arrive on expand */
    for (var i = 0; i < r.inputs_total; i++) {
      bars += '<div class="pf-idx-bar' + (i < r.inputs_live ? '' : ' off') + '"><i style="width:' +
        (i < r.inputs_live ? '100' : '0') + '%"></i></div>';
    }
    /* Flow 4 (cross-data): every score deep-links — politicians to their
       Receipt dossier, companies to their extraction profile (Receipts
       don't apply to companies). */
    var deep = '';
    if (r.kind === 'company' && r.extraction_url) {
      deep = '<div class="pf-idx-meta"><a href="' + esc(r.extraction_url) +
        '" style="color:#e8b923;font-weight:700;text-decoration:none">EXTRACTION FILE →</a></div>';
    } else if (r.receipt_url) {
      deep = '<div class="pf-idx-meta"><a href="' + esc(r.receipt_url) +
        '" style="color:#e8b923;font-weight:700;text-decoration:none">GET THE RECEIPT →</a></div>';
    } else if (r.kind !== 'company' && r.slug) {
      deep = '<div class="pf-idx-meta"><a href="/receipt/' + esc(r.slug) +
        '" style="color:#e8b923;font-weight:700;text-decoration:none">GET THE RECEIPT →</a></div>';
    }
    return '<li class="pf-idx-row" data-slug="' + esc(r.slug) + '" data-key="' + esc(r.entity_key) + '">' +
      '<div class="pf-idx-top">' +
      '<div class="pf-idx-rank">#' + r.rank + '</div>' +
      '<div class="pf-idx-who"><div class="pf-idx-name">' + esc(r.name) + '</div>' +
      '<div class="pf-idx-meta">' + metaLine(r) + '</div>' + deep + '</div>' +
      '<div class="pf-idx-score"><div class="pf-idx-num">' + esc(String(r.score)) + '</div>' +
      '<div class="pf-idx-label">' + esc(r.label) + '</div></div></div>' +
      '<div class="pf-idx-bars">' + bars + '</div>' +
      '<div class="pf-idx-detail" id="pf-idx-d-' + esc(r.slug) + '"><div class="pf-idx-load">Loading breakdown…</div></div>' +
      '</li>';
  }

  function inputRowHTML(inp) {
    var v = inp.live && inp.raw_display
      ? '<div class="pf-idx-in-v">' + esc(inp.raw_display) + '</div>'
      : '<div class="pf-idx-in-e">' + esc(inp.status_note || 'not yet tracked') + '</div>';
    var src = inp.source ? '<div class="pf-idx-in-s">SOURCE: ' + esc(inp.source) +
      (inp.cycle ? ' · ' + esc(inp.cycle) : '') +
      (inp.source_url ? ' · <a href="' + esc(inp.source_url) + '" target="_blank" rel="noopener">verify</a>' : '') + '</div>' : '';
    return '<div class="pf-idx-in"><div class="pf-idx-in-t"><span>' + esc(inp.title) + '</span>' +
      '<span class="w">WEIGHT ' + Math.round((inp.weight || 0) * 100) + '%</span></div>' + v + src + '</div>';
  }

  function detailHTML(det) {
    var ins = (det.inputs || []).map(inputRowHTML).join('');
    var shareBtn = det.scored
      ? '<button class="pf-idx-share" data-share="' + esc(det.entity.slug) + '">SHARE THIS SCORE</button>' : '';
    var mssBtn = det.scored
      ? '<button class="pf-mss-btn" data-mss-index="' + esc(det.entity.slug) + '" style="width:100%;margin:8px 0 2px">MAKE SHAREABLE</button>' : '';
    var web = '';
    if (det.neighbors) {
      var links = '';
      if (det.neighbors.town_url) links += '<a href="/town">THEIR TOWN →</a>';
      if (links) web = '<div class="pf-idx-web">' + links + '</div>';
    }
    /* Flow 4 (cross-data): the primary deep-link is kind-aware. Politicians
       -> GET THE FULL RECEIPT (verified: neighbors.receipt_url is
       /receipt/<slug> and the receipt page deep-links it). Companies ->
       GET THE EXTRACTION FILE (Receipts don't apply to companies). */
    var isCo = det.entity && det.entity.kind === 'company';
    var primary = isCo
      ? '<a class="pf-idx-receipt" href="' + esc(det.neighbors && det.neighbors.extraction_url ? det.neighbors.extraction_url : ('/extraction/' + det.entity.slug)) + '">GET THE EXTRACTION FILE →</a>'
      : '<a class="pf-idx-receipt" href="' + esc(det.neighbors && det.neighbors.receipt_url ? det.neighbors.receipt_url : ('/receipt/' + det.entity.slug)) + '">GET THE FULL RECEIPT →</a>';
    var head = det.scored
      ? ''
      : '<div class="pf-idx-in-e" style="margin-bottom:10px">INSUFFICIENT DATA — needs ' + esc(det.threshold || '') + '.</div>';
    return head + ins + primary + web + shareBtn + mssBtn;
  }

  function render() {
    var sc = state.scores;
    var list = state.tab === 'companies' ? (sc ? sc.companies : []) : (sc ? sc.politicians : []);
    var tabBtns = '<div class="pf-idx-tabs">' +
      '<div class="pf-idx-tab' + (state.tab === 'politicians' ? ' on' : '') + '" data-tab="politicians">POLITICIANS</div>' +
      '<div class="pf-idx-tab' + (state.tab === 'companies' ? ' on' : '') + '" data-tab="companies">COMPANIES</div></div>';
    var html = '<div class="pf-idx-head"><div class="pf-idx-kicker">DATA PRODUCT · WEEKLY</div>' +
      '<h1>THE CORRUPTION INDEX</h1>' +
      '<div class="pf-idx-sub">How captured is this entity by moneyed interests. Descriptive scores from public records — never accusations.</div></div>' +
      '<div class="pf-idx-chips">' +
      '<span class="pf-idx-chip">SCORE BAND 7.6–9.8</span>' +
      '<span class="pf-idx-chip">3 OF 4 INPUTS MINIMUM</span>' +
      '<span class="pf-idx-chip">' + (sc && sc.vintage_week ? vintageLine(sc.vintage_week) : 'WEEKLY VINTAGE') + '</span>' +
      '</div>' +
      '<details class="pf-idx-meth"><summary>METHODOLOGY — WEIGHTS, PEERS, RULES +</summary>' +
      methodologyHTML() + '</details>' + tabBtns;
    if (!sc) {
      html += '<div class="pf-idx-load">Loading the index…</div>';
    } else if (!list.length) {
      html += emptyHTML(sc);
    } else {
      html += '<div class="pf-idx-vint">' + vintageLine(sc.vintage_week) + ' · METHODOLOGY ' + esc(sc.methodology_version || 'v1') + '</div>' +
        '<ul class="pf-idx-list">' + list.map(rowHTML).join('') + '</ul>';
    }
    host.innerHTML = html;
    wire();
    deepLink();
  }

  function emptyHTML(sc) {
    var rails = sc.rail_status || {};
    var names = { fec: 'FEC fundraising', lda: 'LDA lobbying', stock_act: 'STOCK Act trades', congress: 'Congress.gov votes', usaspending: 'USAspending contracts', osha: 'OSHA violations', dol: 'DOL wage theft' };
    var items = Object.keys(names).map(function (k) {
      var live = rails[k];
      return '<div>' + (live ? '🟢' : '⚪') + ' ' + esc(names[k]) + (live ? ' — live' : ' — not yet tracked') + '</div>';
    }).join('');
    return '<div class="pf-idx-empty"><h3>NO SCORES YET</h3>' +
      '<p>No entity clears the data threshold yet — politicians need 3 of 4 inputs live, companies need 3 of 3. ' +
      'No scores are shown below the threshold, ever. The index activates as the data rails land:</p>' +
      '<div class="pf-idx-rails">' + items + '</div>' +
      '<p style="margin-top:14px">The methodology above is final. The leaderboard fills in rail by rail.</p></div>';
  }

  function wire() {
    var tabs = host.querySelectorAll('.pf-idx-tab');
    for (var i = 0; i < tabs.length; i++) {
      tabs[i].onclick = function () {
        state.tab = this.getAttribute('data-tab');
        render();
      };
    }
    var rows = host.querySelectorAll('.pf-idx-row');
    for (var j = 0; j < rows.length; j++) {
      rows[j].onclick = function (ev) {
        if (ev.target && (ev.target.tagName === 'A' || ev.target.tagName === 'BUTTON')) return;
        toggleRow(this);
      };
    }
    var shares = host.querySelectorAll('[data-share]');
    for (var k = 0; k < shares.length; k++) {
      shares[k].onclick = function (ev) {
        ev.stopPropagation();
        shareScore(this.getAttribute('data-share'));
      };
    }
  }

  function toggleRow(row) {
    var wasOpen = row.classList.contains('open');
    var all = host.querySelectorAll('.pf-idx-row.open');
    for (var i = 0; i < all.length; i++) all[i].classList.remove('open');
    if (wasOpen) { history.replaceState(null, '', location.pathname); return; }
    row.classList.add('open');
    var key = row.getAttribute('data-key');
    var slug = row.getAttribute('data-slug');
    history.replaceState(null, '', '#' + slug);
    loadDetail(row, key, slug);
  }

  function loadDetail(row, key, slug) {
    var box = row.querySelector('.pf-idx-detail');
    if (!box) return;
    if (state.detailCache[key]) {
      box.innerHTML = detailHTML(state.detailCache[key]);
      wireShares(box);
      return;
    }
    box.innerHTML = '<div class="pf-idx-load">Loading breakdown…</div>';
    jsonp('index_entity', { entity_key: key }, function (det) {
      if (!det || !det.ok) {
        box.innerHTML = '<div class="pf-idx-err">Could not load the breakdown. Try again.</div>';
        return;
      }
      state.detailCache[key] = det;
      box.innerHTML = detailHTML(det);
      wireShares(box);
    });
  }

  function wireShares(root) {
    var btns = root.querySelectorAll('[data-share]');
    for (var i = 0; i < btns.length; i++) {
      btns[i].onclick = function (ev) {
        ev.stopPropagation();
        shareScore(this.getAttribute('data-share'));
      };
    }
    var mss = root.querySelectorAll('[data-mss-index]');
    for (var j = 0; j < mss.length; j++) {
      mss[j].onclick = function (ev) {
        ev.stopPropagation();
        openIndexShareable(this.getAttribute('data-mss-index'));
      };
    }
  }

  function findRow(slug) {
    var sc = state.scores;
    if (!sc) return null;
    var all = sc.politicians.concat(sc.companies);
    for (var i = 0; i < all.length; i++) if (all[i].slug === slug) return all[i];
    return null;
  }

  function scoreCardData(slug) {
    var r = findRow(slug);
    if (!r) return null;
    var det = null;
    for (var k in state.detailCache) {
      if (state.detailCache[k].entity && state.detailCache[k].entity.slug === slug) det = state.detailCache[k];
    }
    var topInputs = det ? det.inputs.filter(function (x) { return x.live && x.raw_display; }).slice(0, 3)
      .map(function (x) { return { title: x.title, display: x.raw_display }; }) : [];
    var sub = state.tab === 'companies' || r.industry ? (r.industry || 'COMPANY')
      : [r.office, r.state, r.party].filter(Boolean).join(' · ');
    return { name: r.name, sub: sub, score: r.score, label: r.label,
      topInputs: topInputs, vintage: vintageLine(state.scores.vintage_week),
      methodology: state.scores.methodology_version || 'v1' };
  }

  function shareScore(slug) {
    var data = scoreCardData(slug);
    if (!data) return;
    try {
      if (PF && PF.PHQShare && PF.PHQShare.share('phq-index-score', data, { link: '/index#' + slug })) return;
    } catch (e) {}
    try {
      if (PF) PF.toast('Poster failed — try again.');
    } catch (e2) {}
  }

  /* MAKE SHAREABLE (fe/make-shareable-inline, 2026-10-07): inline Studio
     creation panel on every score. The score's own 1080x1350 painter
     (phq-index-score, lazy PHQ module) renders the preview — the resolver
     polls until the module lands, so first-tap never wedges. One tap
     publishes to the UGC feed + opens the native share sheet. No page
     navigation. Zero XP for viewing. */
  function openIndexShareable(slug) {
    var M = null;
    try { M = window.PFMakeShareable; } catch (e) {}
    if (!M) return;
    var r = findRow(slug);
    M.openPanel({
      kind: 'index', ref: slug,
      title: 'CORRUPTION INDEX: ' + (r && r.name ? r.name : slug),
      deep: '/index#' + slug, game: 'index'
    });
  }
  function wireMakeShareableIndex() {
    var M = null;
    try { M = window.PFMakeShareable; } catch (e) {}
    if (!M || M._pfIndexWired) return;
    M._pfIndexWired = true;
    M.registerResolver('index', function (unit, done) {
      var d = null;
      try { d = scoreCardData(unit.ref); } catch (e) {}
      if (!d) { try { done(null); } catch (e2) {} return; }
      var PH = null;
      try { PH = PF && PF.PHQShare; } catch (e) {}
      if (!PH || typeof PH.paint !== 'function') { try { done(null); } catch (e2) {} return; }
      try { if (typeof PH._ensure === 'function') PH._ensure(); } catch (e) {}
      var tries = 0;
      (function poll() {
        var cv = null;
        try { cv = PH.paint('phq-index-score', d); } catch (e) {}
        if (cv) { try { done(cv); } catch (e2) {} return; }
        if (++tries > 80) { try { done(null); } catch (e2) {} return; }
        setTimeout(poll, 100);
      })();
    });
  }

  function deepLink() {
    try {
      var h = String(location.hash || '').replace('#', '');
      if (!h) return;
      var row = host.querySelector('.pf-idx-row[data-slug="' + h.replace(/"/g, '') + '"]');
      if (row) {
        row.classList.add('open');
        loadDetail(row, row.getAttribute('data-key'), h);
        setTimeout(function () {
          try { row.scrollIntoView({ behavior: 'smooth', block: 'start' }); } catch (e) {}
        }, 300);
      }
    } catch (e) {}
  }

  function fail(msg) {
    host.innerHTML = '<div class="pf-idx-head"><div class="pf-idx-kicker">DATA PRODUCT</div>' +
      '<h1>THE CORRUPTION INDEX</h1></div>' +
      '<div class="pf-idx-err">' + esc(msg || 'The index is unreachable right now. Try again in a bit.') + '</div>';
  }

  /* boot: scores + methodology in parallel */
  wireMakeShareableIndex();
  jsonp('index_scores', {}, function (sc) {
    if (!sc || !sc.ok) { fail(); return; }
    state.scores = sc;
    jsonp('index_methodology', {}, function (m) {
      if (m && m.ok) state.meth = m;
      render();
    });
  });
})();

;

/* ===== core/share-image-phq-lazy.js ===== */
/* core/share-image-phq-lazy.js  |  PF v1.4.3 | PHQ SHARE-POSTER LAZY LOADER.
   ~1.5KB stub bundled in pages/bundle-pages INSTEAD of the full
   core/share-image-phq.js (~87KB, 23 painters). Creates the PF.PHQShare
   facade (additive registry per the design-system spec §3) and injects the
   full painter module on the FIRST share/save/paint/pledgeData call — the
   ~99% of visitors who never share never pay for the painters.
   Queued share/save calls replay once the module registers; paint() before
   load returns null (honest: nothing painted yet); pledgeData() before load
   returns null (same fail-soft the silos already handle).
   The full module never reassigns this facade: it calls
   PF.PHQShare.registerPainters(), which merges, honors per-painter
   ?pf_off=phq-<painter> kills, sets F._route, and flushes the queue.
   KILL: ?pf_off=phq-share kills stub + module (first executable line). */
(function () {
  'use strict';
  var PF = window.PF;
  if (PF && PF.skip('phq-share')) { return; }
  if (window.pfPhqShareLazy || window.pfPhqShareDone) return;
  window.pfPhqShareLazy = true;

  var LOADING = false;

  function toast(m) { try { if (PF && PF.toast) PF.toast(m); } catch (e) {} }
  /* Derive the versioned CDN base from an already-loaded bundle script,
     e.g. https://cdn.jsdelivr.net/gh/swananas/MTCSTW-site-deploy@<pin>/v1.4.3/pages/bundle-pages.js
     -> https://cdn.jsdelivr.net/gh/swananas/MTCSTW-site-deploy@<pin>/v1.4.3/ */
  function baseUrl() {
    try {
      var ss = document.getElementsByTagName('script');
      for (var i = ss.length - 1; i >= 0; i--) {
        var m = String(ss[i].src || '').match(/^(.*\/v\d+\.\d+\.\d+\/)/);
        if (m) return m[1];
      }
    } catch (e) {}
    return null;
  }
  function loadModule() {
    if (LOADING) return;
    var b = baseUrl();
    if (!b) { toast('Poster failed \u2014 try again.'); return; }
    LOADING = true;
    var s = document.createElement('script');
    s.async = true;
    s.src = b + 'core/share-image-phq.js';
    s.onload = function () { LOADING = false; };
    s.onerror = function () { LOADING = false; toast('Poster failed \u2014 try again.'); };
    try { document.head.appendChild(s); } catch (e) { LOADING = false; }
  }
  function flushQueue(F) {
    var r = null;
    try { r = F._route; } catch (e) {}
    if (!r) return;
    var q = [];
    try { q = F._queue.splice(0, F._queue.length); } catch (e2) {}
    for (var i = 0; i < q.length; i++) {
      try { r[q[i].kind](q[i].id, q[i].data, q[i].opts); } catch (e3) {}
    }
  }
  function mkFacade() {
    var F = {
      ids: [],
      _paint: {},
      _titles: {},
      _route: null,
      _queue: [],
      _flushed: false,
      _ensure: loadModule,
      registerPainters: function (painters, titles) {
        for (var id in painters) {
          if (!painters.hasOwnProperty(id)) continue;
          var skip = false;
          try { skip = PF && PF.skip(id); } catch (e) {}
          if (skip) continue;                          /* per-painter kill */
          F._paint[id] = painters[id];
          if (titles && titles[id] && F._titles[id] == null) F._titles[id] = titles[id];
          if (F.ids.indexOf(id) === -1) F.ids.push(id);
        }
        if (!F._flushed) { F._flushed = true; flushQueue(F); }
        return F;
      },
      share: function (id, data, opts) {
        var r = null;
        try { r = F._route; } catch (e) {}
        if (r) return r.share(id, data, opts);
        F._queue.push({ kind: 'share', id: id, data: data, opts: opts });
        loadModule();
        return true;
      },
      save: function (id, data, opts) {
        var r = null;
        try { r = F._route; } catch (e) {}
        if (r) return r.save(id, data, opts);
        F._queue.push({ kind: 'save', id: id, data: data, opts: opts });
        loadModule();
        return true;
      },
      paint: function (id, data) {
        var r = null;
        try { r = F._route; } catch (e) {}
        if (r) return r.paint(id, data);
        loadModule();
        return null;
      },
      pledgeData: function (row) {
        var r = null;
        try { r = F._route; } catch (e) {}
        if (r && r.pledgeData) return r.pledgeData(row);
        loadModule();
        return null;
      }
    };
    return F;
  }
  try {
    if (!PF.PHQShare || typeof PF.PHQShare.registerPainters !== 'function') {
      /* The single facade-creation site in the bundle path. The full module
         (standalone mode) has its own guarded creation; exactly one wins. */
      PF.PHQShare = mkFacade();
    }
  } catch (e) {}
})();

;

/* ===== core/money-chunk-loader.js ===== */
/* core/money-chunk-loader.js | PF v1.4.3 | FOLLOW THE MONEY — lazy chunk loader.
   2026-10-05 (fix/money-minified-rebuild): the money suite (~65KB raw across
   10 modules) no longer rides in bundle-core.js. It ships as the minified
   core/bundle-money.js chunk, loaded on demand ONLY when a money surface is
   present:
     - <div id="pf-money">          -> the /money page (full-page shell)
     - <div id="pf-political-hq">    -> interim money tab + bill/legislator
       detail consumers (PFMoneyTab / PFMoneyVote / PFWallShame mounts)
   Master kill ?pf_off=money is honored BEFORE the chunk loads, so the kill
   switch keeps working with zero bytes fetched. Fail-soft: if the chunk
   fails to load, the page renders without the money suite (no throw).
   Base-URL resolution follows the established ownBase() pattern
   (core/07-slr-db.js): derive the CDN pin from the executing bundle's
   script src. KILL: ?pf_off=money (master). */
(function () {
  'use strict';
  var PF = window.PF;
  if (!PF) { return; }
  if (PF.skip('money')) { return; }
  if (window.pfMoneyChunkLoading || window.pfMoneyChunkDone) { return; }
  /* 2026-10-05 (fix/crawl-3page-fix): the footer now loads core/bundle-money.js
     directly on /money via the isMoney JS_GAMES entry. If that already ran
     (money-page.js sets window.PFMoney at bundle time), the chunk is
     redundant — skip so we never double-fetch. (Guard reads window.PFMoney,
     not the pfMoneyPageDone marker, so the no-duplication verify keeps
     passing: that marker must only ever be SET inside bundle-money.js.) */
  if (window.PFMoney) { return; }
  var needsMoney = !!document.getElementById('pf-money') ||
                   !!document.getElementById('pf-political-hq');
  if (!needsMoney) { return; }
  window.pfMoneyChunkLoading = true;
  function ownBase() {
    try {
      var src = '';
      if (document.currentScript && document.currentScript.src) src = document.currentScript.src;
      var re = /^(https:\/\/cdn\.jsdelivr\.net\/gh\/[^@]+@[^\/]+\/v1\.4\.3\/)core\/bundle-core(-slr)?\.js/;
      /* src looks like .../v1.4.3/core/bundle-core.js (or bundle-core-slr.js)
         on the pinned CDN when this file runs inside the core bundle.
         Swap the filename for the money chunk. */
      var m = src && src.match(re);
      if (m) { return m[1] + 'core/bundle-money.js'; }
      /* 2026-10-05 (fix/crawl-3page-fix): this loader ships inside
         pages/bundle-pages.js, NOT the core bundle — document.currentScript
         is the pages bundle, so the regex above never matches and the old
         code returned null ('no base') even though the core bundle's script
         tag is right there in the DOM. Fall back to scanning for it. */
      var ss = document.getElementsByTagName('script');
      for (var i = ss.length - 1; i >= 0; i--) {
        var s2 = (ss[i] && ss[i].src) || '';
        var m2 = s2.match(re);
        if (m2) { return m2[1] + 'core/bundle-money.js'; }
      }
    } catch (e) {}
    return null;
  }
  function done() {
    window.pfMoneyChunkLoading = false;
    window.pfMoneyChunkDone = true;
  }
  function fail(m) {
    done();
    try { if (PF && PF.error) PF.error('money-chunk', m); } catch (e) {}
  }
  var url = ownBase();
  if (!url) { fail('no base'); return; }
  var s = document.createElement('script');
  s.async = true;
  s.src = url;
  s.onload = done;
  s.onerror = function () { fail('load error'); };
  document.head.appendChild(s);
  /* Backstop: never leave the loading flag stuck if onload misfires. */
  setTimeout(function () { if (window.pfMoneyChunkLoading) done(); }, 20000);
})();

;

/* ===== core/fred-tools-loader.js ===== */
/* core/fred-tools-loader.js | PF v1.4.3 | FRED EVERYWHERE PHASE 2 — tool chunk loader.
   The three user modeling tools (Stack 'Em, explainer, Receipt check) ship
   as the lazy core/bundle-fred-tools.js chunk, loaded on demand ONLY when a
   tool host exists on the page:
     - <div id="pf-economy">     -> /economy (Receipt check hero + explainer)
     - <div id="xWarReport">      -> /war-report (curated stack + explainer)
     - <div id="xBrief">          -> homepage Morning Briefing (explainer)
     - <div id="pf-academy-hq">   -> Academy (guided Stack 'Em)
   The money page does NOT use this chunk — its tools ride inside the money
   chunk (blocking, synchronous with money-page.js). If the money chunk
   already provided the tools (window.PFStackEm), this loader stands down.
   Master kill ?pf_off=fred is honored BEFORE the chunk loads. Fail-soft:
   if the chunk fails, pages render without the tools (no throw).
   Base-URL resolution follows the money-chunk-loader ownBase() pattern.
   KILL: ?pf_off=fred. */
(function () {
  'use strict';
  var PF = window.PF;
  if (!PF) { return; }
  if (PF.skip('fred')) { return; }
  if (window.pfFredToolsLoading || window.pfFredToolsDone) { return; }
  /* Money chunk already serving the tools (money page): stand down. */
  if (window.PFStackEm || window.PFExplain || window.PFReceipt) { return; }
  var needsTools = false;
  try {
    needsTools = !!document.getElementById('pf-economy') ||
                !!document.getElementById('xWarReport') ||
                !!document.getElementById('xBrief') ||
                !!document.getElementById('pf-academy-hq');
  } catch (e) { needsTools = false; }
  if (!needsTools) { return; }
  window.pfFredToolsLoading = true;
  function ownBase() {
    try {
      var re = /^(https:\/\/cdn\.jsdelivr\.net\/gh\/[^@]+@[^\/]+\/v1\.4\.3\/)core\/bundle-core(-slr)?\.js/;
      if (document.currentScript && document.currentScript.src) {
        var m0 = String(document.currentScript.src).match(re);
        if (m0) { return m0[1] + 'core/bundle-fred-tools.js'; }
      }
      var ss = document.getElementsByTagName('script');
      for (var i = ss.length - 1; i >= 0; i--) {
        var s2 = (ss[i] && ss[i].src) || '';
        var m2 = s2.match(re);
        if (m2) { return m2[1] + 'core/bundle-fred-tools.js'; }
      }
    } catch (e) {}
    return null;
  }
  function done() {
    window.pfFredToolsLoading = false;
    window.pfFredToolsDone = true;
  }
  function fail() { done(); }
  var url = ownBase();
  if (!url) { fail(); return; }
  try {
    var s = document.createElement('script');
    s.src = url;
    s.async = true;
    s.onload = done;
    s.onerror = fail;
    document.head.appendChild(s);
    setTimeout(function () {
      if (window.pfFredToolsLoading) fail();
    }, 15000);
  } catch (e) { fail(); }
})();

;

/* ===== pages/creator-recruit.js ===== */
/* pages/creator-recruit.js  |  PF v1.4.3 | Creator catalog recruiting tools.
   ONE shared component for every SLR catalog render (roster cards +
   individual catalog pages) — no per-creator bespoke code. Auto-mounts:
   - Roster: scans #pf-slr-roster-root .pf-slr-card, resolves each member from
     the card's VIEW PROFILE link (catalog_path -> slug -> PF.slrMember).
   - Catalog page: scans #pf-catalog / #pf-catalog-root, resolves the member
     from data-slug or the URL path.
   Per creator it adds:
   (a) RECRUIT button: mints a shareable creator poster (1080x1350, black/red,
       name, photo, propaganda score, follower count, red bold "JOIN THE FIGHT."
       CTA, MTCSTW.COM branding) and opens the native share sheet via
       PFShare.shareImage (navigator.share with files; download fallback on
       browsers without Web Share API file support). The "FIGHTING AS
       <CALLSIGN>" strip is applied by PFShare.stampCallsign (idempotent).
       The photo is loaded crossOrigin="anonymous" (images.squarespace-cdn.com
       sends ACAO:*) — if it fails, a monogram fallback renders instead, so
       the canvas can never be tainted by a non-CORS image.
   (b) COPY ENLIST LINK button: referral/enlist link per creator
       (https://www.mtcstw.com/request-access?creator=<slug>) run through
       PF.shareUrl so the visitor's callsign rides along as ?ref=<callsign>;
       copy-to-clipboard with a textarea fallback for iOS.
   (c) Catalog pages only: a compact "BRING THEM IN" panel linking at
       /request-access with the creator pre-referenced via ?creator=<slug>.
   Share credit flows through PFShare's once-per-day gate (pf-share-image) so
   the Do Meter / XP ledger count it exactly once. Rescans a few times after
   load because the roster/catalog renderers finish asynchronously once the
   SLR DB resolves; every mount is guarded by data-recruit so it is idempotent.
   KILL: ?pf_off=creator-recruit  or  localStorage pf_disabled_v1='["creator-recruit"]' */
(function () {
  'use strict';
  var PF = window.PF;
  if (!PF || PF.skip('creator-recruit')) { return; }
  if (window.pfCreatorRecruitDone) { return; }
  window.pfCreatorRecruitDone = true;

  var RED = '#c1121f', RED_TX = '#e5383b' /* CONTRAST FIX 2026-10-08: text-safe red, 4.68:1 on #0a0a0a */, CREAM = '#f5f0e1', BLACK = '#0a0a0a', MUTED = '#b8ab8e';
  var SITE = 'https://www.mtcstw.com';

  function esc(s) {
    return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;')
      .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }
  function initials(name) {
    var w = String(name || '?').split(/\s+/).filter(Boolean);
    return ((w[0] || '?').charAt(0) + (w[1] ? w[1].charAt(0) : '')).toUpperCase();
  }
  function toast(msg) {
    try { if (PF && PF.toast) { PF.toast(msg); return; } } catch (e) {}
    try {
      var d = document.createElement('div');
      d.textContent = msg;
      d.style.cssText = 'position:fixed;left:50%;top:14%;transform:translateX(-50%);background:#c1121f;' +
        'color:#fff;font:bold 14px monospace;padding:12px 20px;border:2px solid #fff;z-index:99999;' +
        'max-width:86vw;text-align:center;box-sizing:border-box;';
      document.body.appendChild(d);
      setTimeout(function () { try { d.remove(); } catch (e2) {} }, 2800);
    } catch (e3) {}
  }
  function enlistUrl(member) {
    var u = SITE + '/request-access?creator=' + encodeURIComponent(member.slug);
    try {
      if (PF && typeof PF.shareUrl === 'function') return PF.shareUrl(u);
    } catch (e) {}
    return u;
  }
  function copyText(str, okMsg) {
    function done() { toast(okMsg || 'Copied.'); }
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(str).then(done, function () { legacy(); });
        return;
      }
    } catch (e) {}
    legacy();
    function legacy() {
      try {
        var ta = document.createElement('textarea');
        ta.value = str;
        ta.setAttribute('readonly', '');
        ta.style.cssText = 'position:fixed;top:0;left:0;opacity:0;font-size:16px;';
        document.body.appendChild(ta);
        try { ta.focus(); ta.select(); } catch (e2) {}
        try { ta.setSelectionRange(0, ta.value.length); } catch (e3) {}
        var ok = false;
        try { ok = document.execCommand('copy'); } catch (e4) {}
        ta.remove();
        if (ok) done();
        else toast('Copy failed \u2014 long-press the link to copy it.');
      } catch (e4) { toast('Copy failed \u2014 long-press the link to copy it.'); }
    }
  }

  /* ---- (a) creator poster (1080x1350, black/red/cream) ---- */
  function wrap(x, text, maxW, maxLines) {
    var words = String(text || '').split(/\s+/), lines = [], line = '';
    words.forEach(function (w) {
      var t = line ? line + ' ' + w : w;
      if (x.measureText(t).width > maxW && line) { lines.push(line); line = w; }
      else { line = t; }
    });
    if (line) lines.push(line);
    return lines.slice(0, maxLines || 3);
  }
  /* CORS-safe photo: only resolve an image loaded with crossOrigin set. The
     Squarespace CDN sends Access-Control-Allow-Origin: *; anything else (or
     any failure) resolves null and the monogram fallback keeps the canvas
     untainted. */
  function loadPhoto(url) {
    return new Promise(function (resolve) {
      var done = false;
      function fin(img) { if (!done) { done = true; resolve(img); } }
      if (!url) { fin(null); return; }
      try {
        var img = new Image();
        img.crossOrigin = 'anonymous';
        img.onload = function () { fin(img); };
        img.onerror = function () { fin(null); };
        img.src = url;
        setTimeout(function () { fin(null); }, 8000);
      } catch (e) { fin(null); }
    });
  }
  function drawPoster(member, photo) {
    var W = 1080, H = 1350;
    var cv = document.createElement('canvas');
    cv.width = W; cv.height = H;
    var x = cv.getContext('2d');
    if (!x) return null;
    function center(t, y, font, fill) {
      x.font = font; x.fillStyle = fill; x.textAlign = 'center'; x.textBaseline = 'alphabetic';
      x.fillText(t, W / 2, y);
    }
    /* ---- butter: editorial kit (factgen standard) ---- */
    var btG = '#c9a227';
    x.fillStyle = '#0e0d0c'; x.fillRect(0, 0, W, H);
    x.save(); x.globalAlpha = 0.032; x.strokeStyle = '#ffffff'; x.lineWidth = 1;
    for (var btD = -H; btD < W + H; btD += 26) {
      x.beginPath(); x.moveTo(btD, 0); x.lineTo(btD + H, H); x.stroke();
    }
    x.restore();
    var btVg = x.createRadialGradient(W/2, H*0.40, H*0.16, W/2, H*0.50, H*0.85);
    btVg.addColorStop(0, 'rgba(0,0,0,0)'); btVg.addColorStop(1, 'rgba(0,0,0,0.55)');
    x.fillStyle = btVg; x.fillRect(0, 0, W, H);
    var btBar = x.createLinearGradient(0, 0, 0, 10);
    btBar.addColorStop(0, RED); btBar.addColorStop(1, '#7d0b16');
    x.fillStyle = btBar; x.fillRect(0, 0, W, 10);
    x.save(); x.globalAlpha = 0.05; x.fillStyle = CREAM;
    x.font = '900 620px Arial,sans-serif'; x.textAlign = 'center';
    x.fillText('★', W/2, H*0.60); x.restore();

    var y = 140;
    /* kicker: letterspaced gold */
    x.save();
    try { x.letterSpacing = '10px'; } catch (e) {}
    center('THE PROPAGANDA FACTORY', y, '700 27px Arial,sans-serif', btG);
    x.restore(); y += 40;
    x.strokeStyle = 'rgba(201,162,39,0.5)'; x.lineWidth = 1;
    x.beginPath(); x.moveTo(W/2 - 150, y); x.lineTo(W/2 + 150, y); x.stroke();
    y += 66;
    x.save();
    try { x.letterSpacing = '8px'; } catch (e2) {}
    center('SICK LEFT RADICALS', y, '700 28px Arial,sans-serif', RED);
    x.restore(); y += 72;

    /* Creator name, red bold, up to 2 lines with auto-shrink so long names
       stay inside the frame instead of overflowing. */
    var nameUpper = String(member.name || 'A COMRADE').toUpperCase();
    var nameSize = 72, nameF = '', nameLines = [], nlh = 84;
    while (nameSize >= 44) {
      nameF = '900 ' + nameSize + 'px Georgia,"Times New Roman",serif';
      nlh = Math.round(nameSize * 1.18);
      x.font = nameF;
      nameLines = wrap(x, nameUpper, W - 170, 2);
      var fits = true, li;
      for (li = 0; li < nameLines.length; li++) {
        if (x.measureText(nameLines[li]).width > W - 170) { fits = false; break; }
      }
      if (fits) break;
      nameSize -= 8;
    }
    nameLines.forEach(function (l) { center(l, y, nameF, RED); y += nlh; });

    /* Photo: centered square, cover-fit, red frame. Size adapts to the name
       block so the fixed bottom stack below never shifts. Monogram fallback
       keeps the canvas untainted when no CORS-clean photo loads. */
    var py = y + 28;
    var photoMaxBottom = H - 420;
    var PS = Math.min(560, Math.max(300, photoMaxBottom - py));
    var px = (W - PS) / 2;
    x.fillStyle = '#141414'; x.fillRect(px, py, PS, PS);
    if (photo && photo.naturalWidth > 0) {
      try {
        var iw = photo.naturalWidth, ih = photo.naturalHeight, s = Math.max(PS / iw, PS / ih);
        var dw = iw * s, dh = ih * s;
        x.save();
        x.beginPath(); x.rect(px, py, PS, PS); x.clip();
        x.drawImage(photo, px - (dw - PS) / 2, py - (dh - PS) / 2, dw, dh);
        x.restore();
      } catch (e) { drawMonogram(); }
    } else { drawMonogram(); }
    function drawMonogram() {
      x.fillStyle = RED; x.font = '900 ' + Math.round(PS * 0.38) + 'px Georgia,"Times New Roman",serif';
      x.textAlign = 'center'; x.textBaseline = 'middle';
      x.fillText(initials(member.name), W / 2, py + PS / 2);
      x.textBaseline = 'alphabetic';
    }
    x.strokeStyle = RED; x.lineWidth = 6; x.strokeRect(px, py, PS, PS);

    /* Fixed bottom stack (above the ~70px stamp-clear zone at the very
       bottom, reserved for PFShare.stampCallsign's strip). */
    y = H - 380;
    var labelF = '700 28px Arial,sans-serif';
    x.textAlign = 'center'; x.textBaseline = 'alphabetic';
    var score = Number(member.propaganda_score || 0).toFixed(1) + '/10';
    /* score: letterspaced label + monumental gold figure */
    x.font = labelF; x.fillStyle = MUTED;
    try { x.letterSpacing = '4px'; } catch (e3) {}
    var label = 'PROPAGANDA SCORE ';
    var lw = x.measureText(label).width;
    try { x.letterSpacing = '0px'; } catch (e4) {}
    var valF = '900 56px Georgia,"Times New Roman",serif';
    x.font = valF;
    var vw = x.measureText(score).width;
    x.font = labelF; x.fillStyle = MUTED;
    try { x.letterSpacing = '4px'; } catch (e5) {}
    x.fillText(label, W / 2 - (lw + vw) / 2 + lw / 2, y);
    try { x.letterSpacing = '0px'; } catch (e6) {}
    x.font = valF;
    var btGg = x.createLinearGradient(0, y - 56, 0, y);
    btGg.addColorStop(0, '#f0d060'); btGg.addColorStop(1, '#8a6d1c');
    x.fillStyle = btGg;
    x.fillText(score, W / 2 - (lw + vw) / 2 + lw + vw / 2, y + 6);

    x.save();
    try { x.letterSpacing = '4px'; } catch (e7) {}
    center(String(member.followers_display || '').toUpperCase() + ' FOLLOWERS', H - 304,
      '900 40px Georgia,"Times New Roman",serif', RED);
    x.restore();

    /* ---- butter footer: CTA standard ---- */
    var fy = H - 268;
    x.strokeStyle = 'rgba(201,162,39,0.45)'; x.lineWidth = 1;
    x.beginPath(); x.moveTo(120, fy); x.lineTo(W - 120, fy); x.stroke();
    fy += 58;
    x.font = '900 40px Arial,sans-serif'; x.fillStyle = CREAM;
    try { x.letterSpacing = '8px'; } catch (e8) {}
    var btCta = 'JOIN THE FIGHT';
    var btCtaW = x.measureText(btCta).width;
    x.fillText(btCta, W / 2, fy);
    x.fillStyle = RED; x.fillText('.', W / 2 + btCtaW/2 - 4, fy);
    try { x.letterSpacing = '0px'; } catch (e9) {}
    fy += 52;
    x.fillStyle = RED; x.font = '900 32px Arial,sans-serif';
    try { x.letterSpacing = '10px'; } catch (e10) {}
    x.fillText('MTCSTW.COM', W / 2, fy);
    try { x.letterSpacing = '0px'; } catch (e11) {}
    var btBar2 = x.createLinearGradient(0, H - 10, 0, H);
    btBar2.addColorStop(0, '#7d0b16'); btBar2.addColorStop(1, RED);
    x.fillStyle = btBar2; x.fillRect(0, H - 10, W, 10);
    return cv;
  }

  function busyOn(btn, label) {
    try {
      btn.disabled = true;
      if (!btn._pfLabel) btn._pfLabel = btn.textContent;
      btn.textContent = label || 'MINTING\u2026';
    } catch (e) {}
  }
  function busyOff(btn) {
    try {
      btn.disabled = false;
      if (btn._pfLabel) btn.textContent = btn._pfLabel;
    } catch (e) {}
  }

  /* The share engine (core/share-image.js) normally loads in the core
     bundle; if it isn't up yet, poll a few times before declaring a REAL
     failure. 2026-10-04: terminal state is a retry button on the RECRUIT
     button itself — not an eternal "tap again" toast. */
  function shareEngineWait(btn, member, attempt) {
    if (window.PFShare && typeof window.PFShare.shareImage === 'function') {
      handleRecruit(btn, member);
      return;
    }
    if (attempt < 4) {
      busyOn(btn, 'LOADING\u2026');
      setTimeout(function () { shareEngineWait(btn, member, attempt + 1); }, 700);
      return;
    }
    busyOff(btn);
    try {
      btn.disabled = false;
      btn.textContent = 'SHARE ENGINE FAILED \u2014 TAP TO RETRY';
      btn.onclick = function () {
        try { btn._pfLabel = 'RECRUIT'; btn.textContent = 'RECRUIT'; } catch (e) {}
        handleRecruit(btn, member);
      };
    } catch (e) { toast('Share engine failed to load \u2014 reload the page and try again.'); }
  }

  function handleRecruit(btn, member) {
    if (!window.PFShare || typeof window.PFShare.shareImage !== 'function') {
      shareEngineWait(btn, member, 0);
      return;
    }
    busyOn(btn);
    loadPhoto(member.picture).then(function (photo) {
      var cv = null;
      try { cv = drawPoster(member, photo); } catch (e) { cv = null; }
      busyOff(btn);
      if (!cv) { toast('Poster failed \u2014 try again.'); return; }
      try {
        window.PFShare.shareImage(cv,
          'slr-recruit-' + String(member.slug || 'creator') + '.png',
          (member.name || 'A Sick Left Radical') + ' \u2014 Sick Left Radicals',
          'slr-recruit');
      } catch (e) { toast('Share unavailable here.'); }
    });
  }

  function mkBtn(label, solid) {
    var b = document.createElement('button');
    b.type = 'button';
    b.textContent = label;
    b.setAttribute('data-recruit-btn', '1');
    b.style.cssText = 'display:inline-block;' +
      (solid ? 'background:' + RED + ';border:2px solid ' + RED + ';color:#ffffff;'
             : 'background:transparent;border:2px solid ' + CREAM + ';color:' + CREAM + ';') +
      'padding:0.65rem 1.1rem;margin:0.35rem;font-size:0.78rem;font-weight:900;' +
      'letter-spacing:0.12em;cursor:pointer;font-family:inherit;-webkit-appearance:none;';
    return b;
  }

  /* Toolbar: [RECRUIT] [COPY ENLIST LINK] — shared by cards and pages. */
  function mountToolbar(host, member) {
    if (!host || host.querySelector('[data-recruit-bar]')) return;
    var bar = document.createElement('div');
    bar.setAttribute('data-recruit-bar', '1');
    bar.style.cssText = 'text-align:center;margin:1rem 0 0.4rem;';
    var r = mkBtn('RECRUIT', true);
    r.onclick = function () { handleRecruit(r, member); };
    var c = mkBtn('COPY ENLIST LINK', false);
    c.onclick = function () {
      copyText(enlistUrl(member), 'Enlist link copied \u2014 share it anywhere.');
    };
    bar.appendChild(r);
    bar.appendChild(c);
    host.appendChild(bar);
  }

  /* (c) compact BRING THEM IN panel — catalog pages only. */
  function mountBringThemIn(root, member) {
    if (!root || root.querySelector('[data-bring-them-in]')) return;
    var box = document.createElement('div');
    box.setAttribute('data-bring-them-in', '1');
    box.style.cssText = 'border:3px solid ' + RED + ';background:#141010;padding:1.4rem 1.2rem;' +
      'text-align:center;margin:2.2rem auto 0;max-width:560px;box-sizing:border-box;';
    var inner =
      '<div style="color:' + RED_TX + ';font-weight:900;letter-spacing:0.14em;font-size:1rem;margin-bottom:0.5rem;">' +
      '\u2691 BRING THEM IN</div>' +
      '<div style="color:' + CREAM + ';font-size:0.92rem;line-height:1.55;margin-bottom:1rem;">' +
      'Know a propagandist who belongs on this roster? Send them the enlistment link with ' +
      '<strong>' + esc(member.name) + '</strong> as your reference.</div>' +
      '<a href="' + esc(enlistUrl(member)) + '" style="display:inline-block;background:' + RED + ';color:#fff;' +
      'font-weight:900;letter-spacing:0.12em;font-size:0.9rem;padding:0.8rem 1.8rem;text-decoration:none;">' +
      'GET THE ENLIST LINK \u2192</a>';
    box.innerHTML = inner;
    var container = root.querySelector('div[style*="max-width:720px"]') || root;
    container.appendChild(box);
  }

  /* ---- Roster cards ---- */
  function slugFromPath(p) {
    var seg = String(p || '').split('?')[0].replace(/^\/|\/$/g, '').split('/').pop();
    return seg || '';
  }
  function enhanceCards() {
    var root = document.getElementById('pf-slr-roster-root') || document.getElementById('pf-slr-roster');
    if (!root) return;
    if (typeof PF.slrMember !== 'function') return;
    var cards = root.querySelectorAll('.pf-slr-card');
    for (var i = 0; i < cards.length; i++) {
      var card = cards[i];
      if (card.getAttribute('data-recruit')) continue;
      card.setAttribute('data-recruit', '1');
      var a = card.querySelector('a[href]');
      var member = a ? PF.slrMember(slugFromPath(a.getAttribute('href'))) : null;
      if (!member) continue;
      var body = a.parentNode || card;
      var bar = document.createElement('div');
      bar.setAttribute('data-recruit-bar', '1');
      bar.style.cssText = 'display:flex;gap:0.5rem;margin-top:0.6rem;';
      var r = mkBtn('RECRUIT', true);
      r.style.cssText += 'flex:1;margin:0;font-size:0.72rem;padding:0.6rem 0.5rem;';
      var c = mkBtn('\u2398', false);
      c.title = 'Copy enlist link';
      c.setAttribute('aria-label', 'Copy enlist link for ' + member.name);
      c.style.cssText += 'flex:0 0 auto;margin:0;font-size:0.85rem;padding:0.6rem 0.8rem;';
      (function (m, rb, cb) {
        rb.onclick = function () { handleRecruit(rb, m); };
        cb.onclick = function () { copyText(enlistUrl(m), 'Enlist link copied \u2014 share it anywhere.'); };
      })(member, r, c);
      bar.appendChild(r);
      bar.appendChild(c);
      body.appendChild(bar);
    }
  }

  /* ---- Catalog page ---- */
  function enhanceCatalogPage() {
    var root = document.getElementById('pf-catalog-root') || document.getElementById('pf-catalog');
    if (!root || root.getAttribute('data-recruit')) return;
    if (typeof PF.slrMember !== 'function') return;
    var el = document.getElementById('pf-catalog');
    var slug = (el && el.getAttribute('data-slug')) || slugFromPath(location.pathname);
    var member = slug ? PF.slrMember(slug) : null;
    if (!member) return;
    root.setAttribute('data-recruit', '1');
    var h1 = root.querySelector('h1');
    var wrap2 = document.createElement('div');
    if (h1 && h1.parentNode) h1.parentNode.insertBefore(wrap2, h1.nextSibling);
    else root.appendChild(wrap2);
    mountToolbar(wrap2, member);
    mountBringThemIn(root, member);
  }

  function scan() {
    try { enhanceCards(); } catch (e) { try { PF.error('creator-recruit', e); } catch (e2) {} }
    try { enhanceCatalogPage(); } catch (e3) { try { PF.error('creator-recruit', e3); } catch (e4) {} }
  }

  /* The roster/catalog renderers fire asynchronously once the SLR DB
     resolves (snapshot, lazy script, or JSON fallback — up to ~15s). Scan
     now and on a bounded backoff so we catch late renders without a
     permanent observer. */
  [0, 1500, 4000, 8000, 16000].forEach(function (ms) {
    setTimeout(scan, ms);
  });

  /* Public surface for any other silo that renders catalog content later. */
  try {
    PF.creatorRecruit = {
      scan: scan,
      enlistUrl: enlistUrl,
      recruitPoster: function (member, photo) { return drawPoster(member, photo); }
    };
  } catch (e) {}
})();

;

/* ===== pages/recruit-welcome.js ===== */
/* pages/recruit-welcome.js  |  PF v1.4.3 | R5: recruit-link -> guided first hour.
   ?creator=<slug> traffic lands on /request-access (see pages/creator-recruit.js
   "COPY ENLIST LINK"). This renders the guided first-hour welcome card for
   those arrivals: "X RECRUITED YOU" + the recruiting creator's real catalog
   card (PF.slrMember roster DB data only — never invented), then 3 prescribed
   steps: 1) claim callsign (PF.requireCallsign, the register flow), 2) Route
   March stop 1 (S1 circuit_status deep-link, ?creator= preserved), 3) today's
   seeded NEXT OP (scrolls to the S4 pf-nextop card in-flow).
   Attribution: ?creator= is first-touch persisted by core/09-referral.js
   (pf_creator_ref_v1) and carried explicitly in the Route March deep-link,
   so it survives through to the first circuit claim (S3 race coherence).
   The recruit minimum bar (callsign + 1 Daily Orders mission) stays
   backend-side — this card grants nothing and bypasses nothing.
   Jeanine Pirreaux Comedy: excluded (do not touch).
   KILL: ?pf_off=recruit-welcome  or  localStorage pf_disabled_v1='["recruit-welcome"]' */
(function () {
  'use strict';
  var PF = window.PF;
  if (!PF || PF.skip('recruit-welcome')) { return; }
  if (window.pfRecruitWelcomeDone) { return; }
  window.pfRecruitWelcomeDone = true;

  var DIS_KEY = 'pf_recruit_welcome_dismissed_v1';
  var NO_TOUCH_SLUGS = { 'jeanine-pirreaux-comedy': 1 };

  function esc(s) {
    return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;')
      .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }
  function onRequestAccess() {
    try { return /(^|\/)request-access(\/|$)/.test(location.pathname || ''); } catch (e) { return false; }
  }
  function dismissed(slug) {
    try {
      var o = JSON.parse(localStorage.getItem(DIS_KEY) || '{}');
      return !!(o && o[slug]);
    } catch (e) { return false; }
  }
  function markDismissed(slug) {
    try {
      var o = {};
      try { o = JSON.parse(localStorage.getItem(DIS_KEY) || '{}'); } catch (e2) { o = {}; }
      o[slug] = 1;
      localStorage.setItem(DIS_KEY, JSON.stringify(o));
    } catch (e) {}
  }
  function hasCallsign() {
    try { if (PF && typeof PF.hasCallsign === 'function') return PF.hasCallsign(); } catch (e) {}
    try { return !!(window.PFCallsign && window.PFCallsign()); } catch (e2) { return false; }
  }
  function myCallsign() {
    try { if (window.PFCallsign) return window.PFCallsign() || ''; } catch (e) {}
    return '';
  }
  function creatorSlug() {
    try { if (PF && typeof PF.storedCreatorRef === 'function') return PF.storedCreatorRef() || ''; } catch (e) {}
    return '';
  }

  /* Route March stop-1 deep-link (S1). Self-contained (no cross-file
     ordering dependency with the R1 graduation card): reads circuit_status,
     navigates to stops[0].page with ?creator= preserved for race coherence.
     Guarded — falls back to the homepage briefing if the circuit read fails. */
  function goRouteMarch(btn, slug) {
    function fallback() {
      try { location.href = '/#pf-brief'; } catch (e) {}
    }
    if (btn) { btn.disabled = true; btn.textContent = 'FINDING STOP 1\u2026'; }
    var BACKEND = window.PF_BACKEND_URL;
    var cs = myCallsign();
    function nav(page) {
      var url = String(page || '/#pf-brief');
      if (slug) url += (url.indexOf('?') >= 0 ? '&' : '?') + 'creator=' + encodeURIComponent(slug);
      try { location.href = url; } catch (e) { fallback(); }
    }
    if (!BACKEND || !cs) { fallback(); return; }
    var finished = false;
    function done(j) {
      if (finished) return; finished = true;
      try {
        if (j && j.ok && j.stops && j.stops.length && j.stops[0].page) { nav(j.stops[0].page); return; }
      } catch (e2) {}
      fallback();
    }
    try {
      if (window.PF && PF.authGetJSONP) { PF.authGetJSONP(BACKEND, 'circuit_status', { callsign: cs }, done); }
      else {
        var fn = 'pfRwRm' + Math.floor(Math.random() * 1e9);
        window[fn] = function (j) { try { delete window[fn]; } catch (e3) {} done(j); };
        var s = document.createElement('script');
        s.onerror = function () { done(null); };
        s.src = BACKEND + '?action=circuit_status&callsign=' + encodeURIComponent(cs) + '&callback=' + fn;
        document.head.appendChild(s);
      }
    } catch (e4) { done(null); }
    setTimeout(function () { done(null); }, 10000);
  }

  function memberCard(member) {
    var name = String(member.name || 'A Sick Left Radical');
    var score = (member.propaganda_score != null) ? Number(member.propaganda_score).toFixed(1) : '';
    var followers = String(member.followers_display || '');
    var path = String(member.catalog_path || ('/' + member.slug));
    var photo = String(member.picture || '');
    var h = '<div style="display:flex;gap:.9rem;align-items:center;text-align:left;' +
      'border:2px solid #c1121f;background:#141010;padding:.8rem;margin:.9rem auto;max-width:480px;box-sizing:border-box;">';
    if (photo) {
      h += '<img src="' + esc(photo) + '" alt="' + esc(member.image_alt || (name + ' — Sick Left Radicals')) + '" ' +
        'loading="lazy" style="width:72px;height:72px;object-fit:cover;flex:0 0 auto;border:2px solid #c1121f;" />';
    }
    h += '<div style="min-width:0;">' +
      '<div style="color:#f5f0e1;font-weight:900;letter-spacing:.06em;font-size:.95rem;">' + esc(name.toUpperCase()) + '</div>' +
      '<div style="color:#b8ab8e;font-size:.75rem;margin-top:.25rem;">' +
      (score ? 'PROPAGANDA SCORE ' + esc(score) + '/10' : '') +
      (score && followers ? ' &middot; ' : '') +
      (followers ? esc(followers.toUpperCase()) + ' FOLLOWERS' : '') + '</div>' +
      '<div style="margin-top:.4rem;"><a href="' + esc(path) + '" ' +
      'style="color:#fff;font-size:.72rem;font-weight:900;letter-spacing:.1em;text-decoration:underline;">' +
      'VIEW ' + esc(name.toUpperCase()) + '\u2019S PAGE &rarr;</a></div>' +
      '</div></div>';
    return h;
  }

  function render(slug, member) {
    if (document.getElementById('pf-recruit-welcome')) return;
    var name = String(member.name || 'A Sick Left Radical');
    var card = document.createElement('div');
    card.id = 'pf-recruit-welcome';
    card.setAttribute('data-pf-recruit-welcome', '1');
    card.style.cssText = 'border:4px solid #c1121f;background:#0d0d0d;color:#f5f0e1;' +
      'padding:1.5rem 1.2rem;margin:0 0 1.4rem;text-align:center;box-sizing:border-box;' +
      'box-shadow:0 0 30px rgba(193,18,31,.4);font-family:inherit;';

    var claimed = hasCallsign();
    var step1 = claimed
      ? '<div style="margin:.55rem 0;padding:.7rem;border:2px solid #2f7a3d;background:#0a140a;">' +
        '<div style="color:#7ddf8a;font-weight:900;letter-spacing:.1em;font-size:.85rem;">&#10003; CALLSIGN CLAIMED &mdash; ' +
        esc(myCallsign().toUpperCase()) + '</div></div>'
      : '<div style="margin:.55rem 0;"><button type="button" id="pf-rw-claim" ' +
        'style="display:inline-block;background:#c1121f;border:2px solid #c1121f;color:#fff;' +
        'font-weight:900;letter-spacing:.12em;padding:.8rem 1.6rem;font-size:.85rem;cursor:pointer;">' +
        '1 &mdash; CLAIM YOUR CALLSIGN</button>' +
        /* 2026-10-06 CEO directive: every claim prompt needs the recovery path. */
        (function(){ try{ return (window.PF && PF.recoverLinkHTML) ? PF.recoverLinkHTML() : ''; }catch(e){ return ''; } })() +
        '</div>';
    var step2 = '<div style="margin:.55rem 0;"><button type="button" id="pf-rw-march" ' +
      'style="display:inline-block;background:transparent;border:2px solid #c1121f;color:#f5f0e1;' +
      'font-weight:900;letter-spacing:.12em;padding:.8rem 1.6rem;font-size:.85rem;cursor:pointer;">' +
      '2 &mdash; ROUTE MARCH: STOP 1 &rarr;</button>' +
      '<div style="font-size:.72rem;color:#b8ab8e;margin-top:.35rem;">Walk the circuit. The first stop is where streaks start.</div></div>';
    var step3 = '<div style="margin:.55rem 0;"><button type="button" id="pf-rw-nextop" ' +
      'style="display:inline-block;background:transparent;border:2px solid #f5f0e1;color:#f5f0e1;' +
      'font-weight:900;letter-spacing:.12em;padding:.8rem 1.6rem;font-size:.85rem;cursor:pointer;">' +
      '3 &mdash; SEE TODAY\u2019S NEXT OP &darr;</button></div>';

    card.innerHTML =
      '<div style="color:#e5383b;font-weight:900;letter-spacing:.16em;font-size:1.05rem;margin-bottom:.3rem;">' +
      '&#9873; ' + esc(name.toUpperCase()) + ' RECRUITED YOU</div>' +
      '<div style="font-size:.85rem;color:#b8ab8e;line-height:1.55;">' +
      esc(name) + ' fights with the Sick Left Radicals. Now it\u2019s your turn &mdash; ' +
      'your first hour, prescribed:</div>' +
      memberCard(member) +
      '<div style="color:#f5f0e1;font-weight:900;letter-spacing:.14em;font-size:.85rem;margin:1rem 0 .4rem;">' +
      'YOUR FIRST HOUR</div>' +
      step1 + step2 + step3 +
      '<div style="margin-top:.8rem;"><button type="button" id="pf-rw-dismiss" ' +
      'style="background:none;border:none;color:#b8ab8e;font-size:.72rem;letter-spacing:.1em;' +
      'cursor:pointer;text-decoration:underline;">dismiss</button></div>';

    /* Mount in-flow at the top of the Academy block (the recruit's first
       stop on /request-access); fall back to the war-card block, then body. */
    var anchor = null;
    try {
      var hq = document.getElementById('pf-academy-hq');
      var hqb = hq && hq.closest ? hq.closest('.fe-block') : null;
      anchor = hqb || null;
      if (!anchor) {
        var wc = document.getElementById('pf-war-card');
        anchor = (wc && wc.closest) ? wc.closest('.fe-block') : null;
      }
    } catch (e) { anchor = null; }
    try {
      if (anchor && anchor.parentNode) anchor.parentNode.insertBefore(card, anchor);
      else if (document.body) document.body.insertBefore(card, document.body.firstChild);
      else return;
    } catch (e2) { return; }

    function dismiss() {
      markDismissed(slug);
      try { if (card.parentNode) card.parentNode.removeChild(card); } catch (e3) {}
    }
    var dis = card.querySelector('#pf-rw-dismiss');
    if (dis) dis.onclick = dismiss;

    var claimBtn = card.querySelector('#pf-rw-claim');
    if (claimBtn) claimBtn.onclick = function () {
      try {
        if (window.PF && PF.requireCallsign) {
          PF.requireCallsign(function (cs) {
            /* The pf-callsign-claimed listener in core/09-referral.js logs
               the recruit_log row with this creator as recruiter — the
               backend minimum bar counts it from there. */
            if (cs) dismiss();
          }, { context: 'to answer ' + name + '\u2019s call' });
        }
      } catch (e4) {}
    };

    var marchBtn = card.querySelector('#pf-rw-march');
    if (marchBtn) marchBtn.onclick = function () { goRouteMarch(marchBtn, slug); };

    var opBtn = card.querySelector('#pf-rw-nextop');
    if (opBtn) opBtn.onclick = function () {
      /* S4 NEXT OP card mounts in-flow above the footer on every page. */
      var t = null;
      try { t = document.getElementById('pf-nextop'); } catch (e5) {}
      if (t) {
        try { t.scrollIntoView({ behavior: 'smooth', block: 'start' }); } catch (e6) {}
      } else {
        try { location.href = '/#pf-orders'; } catch (e7) {}
      }
    };
  }

  function resolveAndRender(slug, triedLazy) {
    var member = null;
    try { member = (PF && typeof PF.slrMember === 'function') ? PF.slrMember(slug) : null; } catch (e) {}
    if (member && member.name) { render(slug, member); return; }
    /* Roster DB may still be resolving on slim-core pages — one lazy retry. */
    if (!triedLazy) {
      try {
        if (PF && typeof PF.ensureSLRDB === 'function') {
          PF.ensureSLRDB().then(function () { resolveAndRender(slug, true); });
          return;
        }
      } catch (e2) {}
      setTimeout(function () { resolveAndRender(slug, true); }, 4000);
    }
    /* Real roster data only — never render with invented creator data. */
  }

  function boot() {
    try {
      if (!onRequestAccess()) return;
      var slug = creatorSlug();
      if (!slug || NO_TOUCH_SLUGS[slug]) return;
      if (dismissed(slug)) return;
      if (document.getElementById('pf-recruit-welcome')) return;
      resolveAndRender(slug, false);
    } catch (e) {}
  }
  /* 09-referral.js captures ?creator= at parse time; the SLR snapshot ships
     inside the SLR core on HQ pages, so the member resolves synchronously in
     practice. Bounded retries catch late renders. */
  [0, 1200, 3500, 8000].forEach(function (ms) { setTimeout(boot, ms); });
})();

;